            let mut children: Vec<FileInfo> = Vec::new();

            for entry in entries {
                if let Ok(entry) = entry {
                    let entry_path = entry.path();

                    if should_exclude(&entry_path, &options.exclude_patterns, options.no_hidden) {
                        continue;
                    }

                    // Skip directories if files_only is set and not in the root depth
                    if options.files_only {
                        if let Ok(metadata) = fs::metadata(&entry_path) {
                            if metadata.is_dir() {
                                continue;
                            }
                        }
                    }

                    // Check depth constraint
                    let should_recurse = if let Some(max_depth) = options.depth {
                        current_depth < max_depth
                    } else {
                        true
                    };

                    if should_recurse {
                        if let Ok(child_info) = scan_directory(&entry_path, options, current_depth + 1) {
                            children.push(child_info);
                        }
                    } else {
                        // Don't recurse, but add the item as is
                        if let Ok(metadata) = fs::metadata(&entry_path) {
                            let name = entry_path
                                .file_name()
                                .and_then(|n| n.to_str())
