        "0 B".to_string()
    } else if size < 1024 {
        format!("{} B", size)
    } else if size < 1024 * 1024 {
        format!("{:.2} KiB", size as f64 / 1024.0)
    } else if size < 1024 * 1024 * 1024 {
        format!("{:.2} MiB", size as f64 / (1024.0 * 1024.0))
    } else {
        format!("{:.2} GiB", size as f64 / (1024.0 * 1024.0 * 1024.0))
    }
}

fn should_exclude(path: &Path, patterns: &[Regex], no_hidden: bool) -> bool {
    if let Some(name) = path.file_name() {
        if let Some(name_str) = name.to_str() {
            if no_hidden && name_str.starts_with('.') {
                return true;
            }

            for pattern in patterns {
                if pattern.is_match(name_str) {
                    return true;
                }
            }
        }
    }
    false
}

fn get_disk_usage(path: &Path) -> u64 {
    match fs::metadata(path) {
        Ok(metadata) => {
            // Disk usage is typically in 4KB blocks
            let blocks = (metadata.blocks() as u64) * 512;
            blocks
        }
        Err(_) => 0,
    }
}

fn scan_directory(
    path: &Path,
    options: &Options,
    current_depth: usize,
) -> Result<FileInfo, Box<dyn std::error::Error>> {
    let metadata = fs::metadata(path)?;
    let name = path
        .file_name()
        .and_then(|n| n.to_str())
        .unwrap_or("<unknown>")
        .to_string();

    let size = metadata.len();
    let disk_usage = if options.usage {
        get_disk_usage(path)
    } else {
        size
    };

    let mut info = FileInfo {
        name,
        size,
        disk_usage,
        is_dir: metadata.is_dir(),
        children: Vec::new(),
    };

    if metadata.is_dir() {
        if let Ok(entries) = fs::read_dir(path) {
            let mut children: Vec<FileInfo> = Vec::new();

            for entry in entries {
                if let Ok(entry) = entry {
                    let entry_path = entry.path();

                    if should_exclude(&entry_path, &options.exclude_patterns, options.no_hidden) {
                        continue;
                    }

                    // Skip directories if files_only is set and not in the root depth
                    if options.files_only {
                        if let Ok(metadata) = fs::metadata(&entry_path) {
                            if metadata.is_dir() {
                                continue;
                            }
                        }
                    }

                    // Check depth constraint
                    let should_recurse = if let Some(max_depth) = options.depth {
                        current_depth < max_depth
                    } else {
                        true
                    };

                    if should_recurse {
                        if let Ok(child_info) = scan_directory(&entry_path, options, current_depth + 1) {
                            children.push(child_info);
                        }
                    } else {
                        // Don't recurse, but add the item as is
                        if let Ok(metadata) = fs::metadata(&entry_path) {
                            let name = entry_path
                                .file_name()
                                .and_then(|n| n.to_str())
                                .unwrap_or("<unknown>")
                                .to_string();
                            let size = metadata.len();
                            let disk_usage = if options.usage {
                                get_disk_usage(&entry_path)
                            } else {
                                size
                            };
                            children.push(FileInfo {
                                name,
                                size,
                                disk_usage,
                                is_dir: metadata.is_dir(),
                                children: Vec::new(),
                            });
                        }
                    }
                }
            }

            // Sort children by size (descending)
            children.sort_by(|a, b| {
                let a_size = if options.usage { a.disk_usage } else { a.size };
                let b_size = if options.usage { b.disk_usage } else { b.size };
                b_size.cmp(&a_size)
            });

            info.children = children;
        }

        // Recalculate size
        info.size = info
            .children
            .iter()
            .map(|c| c.size)
            .sum();
        info.disk_usage = info
            .children
            .iter()
            .map(|c| c.disk_usage)
            .sum();
    }

    Ok(info)
}

fn aggregate_small_files(info: &mut FileInfo, min_size: u64) {
    if !info.children.is_empty() {
        for child in &mut info.children {
            aggregate_small_files(child, min_size);
        }

        let mut aggregated_size = 0u64;
        let mut aggregated_disk_usage = 0u64;
        let mut new_children = Vec::new();

        for child in info.children.drain(..) {
            let child_size = child.size;
            let child_disk_usage = child.disk_usage;

            if child_size < min_size && !child.is_dir {
                aggregated_size += child_size;
                aggregated_disk_usage += child_disk_usage;
            } else {
                new_children.push(child);
            }
        }

        if aggregated_size > 0 {
            new_children.push(FileInfo {
                name: "<aggregated>".to_string(),
                size: aggregated_size,
                disk_usage: aggregated_disk_usage,
                is_dir: false,
                children: Vec::new(),
            });
        }

        new_children.sort_by(|a, b| {
            let a_size = a.size;
            let b_size = b.size;
            b_size.cmp(&a_size)
        });

        info.children = new_children;
    }
}

fn get_color_codes(name: &str) -> (String, String) {
    // Check LS_COLORS environment variable if available
    if let Ok(ls_colors) = env::var("LS_COLORS") {
        // Parse LS_COLORS and apply appropriate colors
        // For now, use simple heuristics

        if name.ends_with('/') || name == "<aggregated>" {
            return ("\x1b[34m".to_string(), "\x1b[0m".to_string()); // Blue for directories
        }

        // Try to extract file type colors from LS_COLORS
        let parts: Vec<&str> = ls_colors.split(':').collect();
        for part in parts {
            if let Some((key, val)) = part.split_once('=') {
                if key == "di" {
                    // Directory color
                    return (format!("\x1b[{}m", val), "\x1b[0m".to_string());
                }
            }
        }
    }

    // Default colors if LS_COLORS not set
    ("".to_string(), "".to_string())
}

fn print_tree(
    info: &FileInfo,
    prefix: &str,
    is_last: bool,
    options: &Options,
    total_size: u64,
) {
    let connector = if is_last { "└─" } else { "├─" };

    let size_to_use = if options.usage { info.disk_usage } else { info.size };

    let display_name = if info.is_dir {
        format!("{}/", info.name)
    } else {
        info.name.clone()
    };

    // Calculate bar width
    let bar_width = 32;
    let percentage = if total_size > 0 {
        ((size_to_use as f64 / total_size as f64) * 100.0) as u32
    } else {
        0
    };
    let filled = ((percentage as usize * bar_width) / 100).max(1).min(bar_width);

    let (color_start, color_end) = if !options.ascii {
        get_color_codes(&display_name)
    } else {
        ("".to_string(), "".to_string())
    };

    let bar_str = if options.ascii {
        "#".repeat(filled) + &" ".repeat(bar_width - filled)
    } else {
        "█".repeat(filled) + &"░".repeat(bar_width - filled)
    };

    let size_str = format_size(size_to_use);

    let name_part = if info.name == "<aggregated>" {
        "<aggregated>".to_string()
    } else {
        format!("{}{}{}", color_start, display_name, color_end)
    };

    println!(
        "{}{}{:<22}│ {}│ {:3}%{:>12}",
        prefix, connector, name_part, bar_str, percentage, size_str
    );

    // Print children
    let extension = if is_last { "   " } else { "│  " };
    for (i, child) in info.children.iter().enumerate() {
        let is_last_child = i == info.children.len() - 1;
        print_tree(child, &format!("{}{}", prefix, extension), is_last_child, options, total_size);
    }
}

fn main() {
    let args: Vec<String> = env::args().collect();

    let mut options = Options::default();
    let mut paths: Vec<PathBuf> = Vec::new();

    let mut i = 1;
    while i < args.len() {
        match args[i].as_str() {
            "-h" | "--help" => {
                println!("Usage: {} [options] <path> [<path>..]", args[0]);
                println!();
                println!("Options:");
                println!("    -d, --depth [DEPTH] show directories up to depth N (def 1)");
                println!("    -a, --aggr [N[KMG]] aggregate smaller than N B/KiB/MiB/GiB (def 1M)");
                println!("    -s, --summary       equivalent to -da, or -d1 -a1M");
                println!("    -u, --usage         report real disk usage instead of file size");
                println!("    -b, --bytes         print sizes in bytes");
                println!("    -f, --files-only    skip directories for a fast local overview");
                println!("    -x, --exclude NAME  exclude matching files or directories");
                println!("    -H, --no-hidden     exclude hidden files");
                println!("    -A, --ascii         ASCII characters only, no colors");
                println!("    -h, --help          show help");
                println!("    -v, --version       print version number");
                return;
            }
            "-v" | "--version" => {
                println!("dutree version {}", VERSION);
                return;
            }
            "-d" | "--depth" => {
                if i + 1 < args.len() {
                    if let Ok(depth) = args[i + 1].parse::<usize>() {
                        options.depth = Some(depth);
                        i += 1;
                    } else {
                        eprintln!("Invalid depth value");
                        return;
                    }
                }
            }
            "-a" | "--aggr" => {
                if i + 1 < args.len() {
                    match parse_size(&args[i + 1]) {
                        Ok(size) => {
                            options.aggr = size;
                            i += 1;
                        }
                        Err(e) => {
                            eprintln!("{}", e);
                            return;
                        }
                    }
                }
            }
            "-s" | "--summary" => {
                options.summary = true;
                options.depth = Some(1);
                options.aggr = 1024 * 1024; // 1M
            }
            "-u" | "--usage" => {
                options.usage = true;
            }
            "-b" | "--bytes" => {
                options.bytes = true;
            }
            "-f" | "--files-only" => {
                options.files_only = true;
            }
            "-x" | "--exclude" => {
                if i + 1 < args.len() {
                    if let Ok(regex) = Regex::new(&args[i + 1]) {
                        options.exclude_patterns.push(regex);
                        i += 1;
                    }
                }
            }
            "-H" | "--no-hidden" => {
                options.no_hidden = true;
            }
            "-A" | "--ascii" => {
                options.ascii = true;
            }
            _ => {
                if !args[i].starts_with('-') {
                    paths.push(PathBuf::from(&args[i]));
                }
            }
        }
        i += 1;
    }

    // Default to current directory if no paths specified
    if paths.is_empty() {
        paths.push(PathBuf::from("."));
    }

    // Set default depth if not specified and not summary
    if options.depth.is_none() && !options.summary {
        options.depth = Some(1);
    }

    // Process multiple paths
    let mut all_infos = Vec::new();
    let mut total_size = 0u64;

    for path in &paths {
        if !path.exists() {
            println!("path {} doesn't exist", path.display());
            std::process::exit(1);
        }

        match scan_directory(path, &options, 0) {
            Ok(mut info) => {
                aggregate_small_files(&mut info, options.aggr);
                total_size += if options.usage { info.disk_usage } else { info.size };
                all_infos.push(info);
            }
            Err(e) => {
                eprintln!("Error scanning {}: {}", path.display(), e);
                std::process::exit(1);
            }
        }
    }

    // If multiple paths, create a collection root
    let root = if all_infos.len() > 1 {
        let mut children = all_infos;
        children.sort_by(|a, b| {
            let a_size = if options.usage { a.disk_usage } else { a.size };
            let b_size = if options.usage { b.disk_usage } else { b.size };
            b_size.cmp(&a_size)
        });

        let mut size = 0u64;
        let mut disk_usage = 0u64;
        for child in &children {
            size += child.size;
            disk_usage += child.disk_usage;
        }

        FileInfo {
            name: "<collection>".to_string(),
            size,
            disk_usage,
            is_dir: true,
            children,
        }
    } else {
        all_infos.into_iter().next().unwrap()
    };

    let total = if options.usage { root.disk_usage } else { root.size };
    println!(
        "[ {} {} ]",
        root.name,
        format_size(total)
    );

    for (i, child) in root.children.iter().enumerate() {
        let is_last = i == root.children.len() - 1;
        print_tree(child, "", is_last, &options, total);
    }
}
